void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float scale = 2.0;
    vec2 uv = scale * (2.0 * fragCoord - iResolution.xy) / iResolution.y;
    uv += iTime * 0.5;
    vec3 col = vec3(1.0);

    // Tamaño del tile
    float tileSize = 1.0;



    // Posición del tile
    vec2 tilePos = floor(uv / tileSize);
    vec2 localPos = fract(uv / tileSize) * tileSize;

    // Selección de rotación aleatoria
    float choice = random(tilePos);
    float ang = 0.0;
    float nopc = 4.0;

    if (choice < 1.0 / nopc) {
        ang = radians(0.0); 
    } else if (choice < 2.0 / nopc) {
        ang = radians(180.0); 
    } else if (choice < 3.0 / nopc) {
        ang = radians(90.0); 
    } else {
        ang = radians(270.0); 
    }

    // Aplica la rotación
    vec2 pos = rotate(localPos - 0.5, ang) + 0.5;
    pos = clamp(pos, 0.0, 1.0); // Asegura que las coordenadas estén dentro de los límites

    // Dibuja la figura en la posición rotada
    col = figura(pos, col);
    //FabriceNeyret2, 2025-01-16
    if (iMouse.z>0.) col *= .6 + .6 * cos( 6.3*random(tilePos)  + vec3(0,23,21)  ); // hue


    // Corrección de gamma
    //col= 1.0-col;
    col = pow(col, vec3(0.554545));
    fragColor = vec4(col, 1.0);
}

